tool trace_reader { version "1"; mode deterministic; }
tool audit_reader { version "1"; mode deterministic; }
evidence first_record { tool first_reader; kind test; environment run_scope; max_age 3600; require "passed" == true; require "subject" == "NW-44"; require "scope" == "load-test-L8"; require "property.operator" == "lt"; require "property.value" == 3; }
evidence second_record { tool second_reader; kind test; environment run_scope; max_age 3600; require "passed" == true; require "subject" == "NW-44"; require "scope" == "load-test-L8"; require "property.operator" == "lt"; require "property.value" == 3; }
